steps.command:
which tesseract || true
python3 - <<'PY'
try:
 import PIL; print('PIL yes',PIL.__version__)
except Exception as e: print('PIL no',e)
PY
apt-cache policy tesseract-ocr 2>/dev/null | head -20 || true

whoami; id; python3 -m pip --version || true
python3 -m pip install --user -q numpy pillow 2>&1 | tail -20
python3 - <<'PY'
try:
 import numpy; print('numpy',numpy.__version__)
except Exception as e: print('no numpy',e)
try:
 import PIL; print('PIL',PIL.__version__)
except Exception as e: print('no PIL',e)
PY

cd /workspace
python3 -m pip install --target /workspace/pylibs -q rapidocr_onnxruntime 2>&1 | tail -30
PYTHONPATH=/workspace/pylibs python3 - <<'PY'
try:
 import rapidocr_onnxruntime as r
 print('rapidocr ok')
except Exception as e:
 import traceback; traceback.print_exc()
PY
